#include "hml_synth_priv.h"

#include "hml/hml_protocol.h"

#include <stdlib.h>
#include <string.h>

/*
 * Synthetic sensor: no hardware, deterministic pattern driven by an absolute byte
 * counter, so any window of the stream can be regenerated by a peer that knows
 * (seed, frame index, frame size).
 */
typedef struct hml_synth_impl {
  hml_synth_cfg cfg;
  uint64_t counter; /* absolute byte index of the next byte to produce */
} hml_synth_impl;

uint8_t hml_synth_pattern_byte(uint64_t index, uint32_t seed) {
  uint32_t x = (uint32_t)index * 2654435761u + seed * 2246822519u;
  x ^= x >> 15;
  x *= 2246822519u;
  x ^= x >> 13;
  return (uint8_t)x;
}

void hml_synth_pattern_fill(uint8_t *dst, size_t n, uint64_t first_index, uint32_t seed) {
  if (!dst) return;
  for (size_t i = 0; i < n; i++) dst[i] = hml_synth_pattern_byte(first_index + i, seed);
}

uint32_t hml_fnv1a32(const void *buf, size_t n) {
  const uint8_t *p = (const uint8_t *)buf;
  uint32_t h = 2166136261u;
  for (size_t i = 0; i < n; i++) {
    h ^= p[i];
    h *= 16777619u;
  }
  return h;
}

static hml_status synth_open(hml_sensor_t *s, void *param) {
  if (!s) return HML_ERR_ARG;
  if (s->impl) return HML_ERR_STATE;

  hml_synth_impl *im = (hml_synth_impl *)calloc(1, sizeof(*im));
  if (!im) return HML_ERR_NOMEM;
  if (param) im->cfg = *(const hml_synth_cfg *)param;
  if (im->cfg.frame_bytes == 0) im->cfg.frame_bytes = (size_t)HML_SYNTH_MAX_ACQUIRE;
  im->counter = 0;
  s->impl = im;
  return HML_OK;
}

static hml_status synth_acquire(hml_sensor_t *s, uint8_t *dst, size_t cap, size_t *out) {
  if (!s || !out) return HML_ERR_ARG;
  *out = 0;
  if (cap > 0 && !dst) return HML_ERR_ARG;

  hml_synth_impl *im = (hml_synth_impl *)s->impl;
  if (!im) return HML_ERR_STATE;

  size_t n = cap < im->cfg.frame_bytes ? cap : im->cfg.frame_bytes;
  hml_synth_pattern_fill(dst, n, im->counter, im->cfg.seed);
  im->counter += n;
  *out = n;
  return HML_OK;
}

static hml_status synth_release(hml_sensor_t *s) {
  if (!s) return HML_ERR_ARG;
  return s->impl ? HML_OK : HML_ERR_STATE;
}

static void synth_close(hml_sensor_t *s) {
  if (!s || !s->impl) return;
  free(s->impl);
  s->impl = NULL;
}

static const hml_sensor_ops g_synth_ops = {"synthetic", synth_open, synth_acquire, synth_release,
                                           synth_close};

const hml_sensor_ops *hml_synth_ops(void) { return &g_synth_ops; }

hml_status hml_synth_register(void) { return HML_OK; }
